CREATE TABLE DEPT (DEPTNO INTEGER PRIMARY KEY NOT NULL, NAME VARCHAR(10) NOT NULL);
CREATE TABLE EMP (EMPNO INTEGER PRIMARY KEY NOT NULL, ENAME VARCHAR(20) NOT NULL, JOB VARCHAR(10) NOT NULL, MGR INTEGER, HIREDATE INTEGER NOT NULL, SAL INTEGER NOT NULL, COMM INTEGER NOT NULL, DEPTNO INTEGER NOT NULL REFERENCES DEPT(DEPTNO), SLACKER INTEGER);
